```python
class Solution:
    def isSubstringPresent(self, s: str) -> bool:
        if len(s) < 2:
            return False

        reverse_s = s[::-1]

        # Check all substrings of length 2 in s
        for i in range(len(s) - 1):
            substring = s[i:i+2]
            if substring in reverse_s:
                return True

        return False
```

```python
class Solution:
    def sumOfTheDigitsOfHarshadNumber(self, x: int) -> int:
        sum_digits = 0
        temp = x

        while temp > 0:
            sum_digits += temp % 10
            temp //= 10

        if x % sum_digits == 0:
            return sum_digits
        else:
            return -1
```

```python
class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        min_len = float('inf')

        # Check all possible subarrays
        for i in range(n):
            current_or = 0
            for j in range(i, n):
                current_or |= nums[j]
                if current_or >= k:
                    min_len = min(min_len, j - i + 1)
                    break
        return min_len if min_len != float('inf') else -1
```

