class Solution:
    def convertDateToBinary(self, date: str) -> str:
        year, month, day = date.split('-')

        def to_binary(n):
            if n == 0:
                return '0'
            binary = ''
            while n > 0:
                binary = str(n % 2) + binary
                n //= 2
            return binary

        return f"{to_binary(int(year))}-{to_binary(int(month))}-{to_binary(int(day))}"
