    # grid[r][c] corresponds to row r (0..H-1) and column c (0..W-1)
    # The input X is 1-indexed in the problem statement but we will treat it as a string of commands.
    # The starting position S_i, S_j is 1-indexed, so we convert to 0-indexed.

    r, c = S_i - 1, S_j - 1

    # Directions: L, R, U, D
    # We can just iterate through the string X

    for char in X:
        if char == 'L':
            if c > 0 and grid[r][c - 1] == '.':
                c -= 1
        elif char == 'R':
            if c < W - 1 and grid[r][c + 1] == '.':
                c += 1
        elif char == 'U':
            if r > 0 and grid[r - 1][c] == '.':
                r -= 1
        elif char == 'D':
            if r < H - 1 and grid[r + 1][c] == '.':
                r += 1

    # Output the result (1-indexed)
    print(f"{r + 1} {c + 1}")

