class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        if n == 0:
            return 0

        # Frequency array for each character
        from collections import Counter
        char_counts = Counter(s)
        total_counts = char_counts.copy()

        # dp[i] = minimum number of balanced substrings needed to partition s[0:i]
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        # Precompute prefix sums for each character
        # prefix_counts[i][char] = count of char in s[0:i]
        prefix_counts = [[0] * 26 for _ in range(n + 1)]
        for i in range(n + 1):
            for char in s:
                if s[i-1] == char:
                    prefix_counts[i][ord(char) - ord('a')] += 1
                else:
                    prefix_counts[i][ord(char) - ord('a')] += 1

        # Calculate minimum substrings
        for i in range(1, n + 1):
            dp[i] = float('inf')
            for j in range(i):
                # Check if s[j:i] is a balanced substring
                substring = s[j:i]
                if len(substring) == 0:
                    continue
                if self._is_balanced(substring):
                    dp[i] = min(dp[i], dp[j] + 1)

        return dp[n]

    def _is_balanced(self, s: str) -> bool:
        counts = Counter(s)
        return all(count == 0 for count in counts.values() if count > 0)
