class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        if n < k:
            return 0

        # For each character, find all substrings where it appears at least k times
        # Then use inclusion-exclusion to count unique substrings
        count = 0

        # Precompute positions for each character
        char_positions = {}
        for i, char in enumerate(s):
            if char not in char_positions:
                char_positions[char] = []
            char_positions[char].append(i)

        # For each character, count substrings where it appears at least k times
        for char, positions in char_positions.items():
            if len(positions) < k:
                continue

            # Count valid substrings for this character
            # A substring is valid if it contains at least k occurrences of this character
            # We can use a sliding window approach
            window_size = k
            window_count = 0
            valid_count = 0

            # For each starting position, count valid windows
            for i in range(n - window_size + 1):
                # Count characters in window
                window = s[i:i+window_size]
                char_counts = {}
                for char in window:
                    char_counts[char] = char_counts.get(char, 0) + 1

                # Check if any character appears at least k times
                if any(count >= k for count in char_counts.values()):
                    valid_count += 1

            count += valid_count

        return count
