from operator import mul

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        def lcm(a, b):
            return (a * b) // gcd(a, b)

        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        def calculate_lcm_gcd(arr):
            if not arr:
                return 0, 0
            g = arr[0]
            for x in arr[1:]:
                g = gcd(g, x)
            l = arr[0]
            for x in arr[1:]:
                l = lcm(l, x)
            return l, g

        # Calculate score with no removal
        l, g = calculate_lcm_gcd(nums)
        score = l * g

        # Try removing each element one by one
        for i in range(len(nums)):
            remaining = nums[:i] + nums[i+1:]
            l, g = calculate_lcm_gcd(remaining)
            score = max(score, l * g)

        return score
